#include <bits/stdc++.h>
using namespace std;
class Solution {
public:
    vector<vector<int>> threeSum(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        unordered_map<int, int> m;            
        set<vector<int>> res;
        for (int i = 0; i < nums.size(); i++) {
            int target = nums[i];
            m.insert({-target, i});
        }
        for (int i = 0; i < nums.size(); i++) {
            for (int j = i+1; j < nums.size(); j++) {
                int a = nums[i];
                int b = nums[j];
                if (m.find(a + b) != m.end() && (m.at(a+b) != i && m.at(a+b) != j)) {
                    vector<int> t = {a, b, -a - b};
                    sort(t.begin(), t.end());
                    res.insert(t);
                } 
            }
        }
        return vector<vector<int>>(res.begin(), res.end());
    }
};
